use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// Reject, among others: leading zeroes (`01.0.0`), missing components
/// (`1.0`), negative numbers, empty identifiers (`1.0.0-`), and whitespace.
pub fn parse(s: &str) -> Result<Version, String> {
    // Basic checks
    if s.is_empty() {
        return Err("empty version".to_string());
    }
    if !s.is_ascii() {
        return Err("non-ASCII characters".to_string());
    }
    if s.lines().any(|l| !l.is_empty()) {
        // allow, but ensure there is no whitespace anywhere in the string
    }
    if s.as_bytes().iter().any(|b| b.is_ascii_whitespace()) {
        return Err("whitespace not allowed".to_string());
    }

    // Only allow a single '+' for build metadata
    if s.matches('+').count() > 1 {
        return Err("invalid build metadata".to_string());
    }

    // Split build metadata
    let (core, build_part): (&str, Option<&str>) = if let Some(idx) = s.find('+') {
        let (left, right) = s.split_at(idx);
        // skip the '+' in the left part
        (left, Some(&right[1..]))
    } else {
        (s, None)
    };

    if let Some(build_str) = build_part {
        if build_str.is_empty() {
            return Err("empty build metadata".to_string());
        }
        // Build identifiers: [0-9A-Za-z-]+ grouped by '.'
        for ident in build_str.split('.') {
            if ident.is_empty() {
                return Err("empty build identifier".to_string());
            }
            if !ident.bytes().all(|b| matches!(b, b'0'..=b'9' | b'A'..=b'Z' | b'a'..=b'z' | b'-')) {
                return Err("invalid characters in build identifier".to_string());
            }
        }
    }

    // Prerelease handling: split on the first '-' if present
    let prerelease_opt: Option<&str> = if let Some(idx) = core.find('-') {
        Some((&core[idx + 1..]))
    } else {
        None
    };
    let core_main = if let Some(idx) = core.find('-') {
        &core[..idx]
    } else {
        core
    };

    // Core must be major.minor.patch with three numbers
    let nums: Vec<&str> = core_main.split('.').collect();
    if nums.len() != 3 {
        return Err("core version must be major.minor.patch".to_string());
    }
    // Parse numbers with leading-zero rules: no leading zeros except single '0'
    let parse_num = |part: &str| -> Result<u64, String> {
        if part.is_empty() {
            return Err("empty numeric component".to_string());
        }
        if !part.chars().all(|c| c.is_ascii_digit()) {
            return Err("non-digit in numeric component".to_string());
        }
        if part.len() > 1 && part.as_bytes()[0] == b'0' {
            return Err("leading zero in numeric component".to_string());
        }
        part.parse::<u64>().map_err(|e| e.to_string())
    };

    let major = parse_num(nums[0])?;
    let minor = parse_num(nums[1])?;
    let patch = parse_num(nums[2])?;

    // Validate prerelease identifiers if present
    let prerelease = if let Some(pr) = prerelease_opt {
        if pr.is_empty() {
            return Err("empty prerelease".to_string());
        }
        // Split by '.' and validate each identifier by SemVer rules
        for ident in pr.split('.') {
            if ident.is_empty() {
                return Err("empty prerelease identifier".to_string());
            }
            // Check allowed: 0 | [1-9]\d* | \d*[a-zA-Z-][0-9a-zA-Z-]*
            // Implement a conservative check matching the Python regex
            let is_all_digits = ident.chars().all(|c| c.is_ascii_digit());
            if is_all_digits {
                // numeric prerelease must be without leading zeros unless it's exactly "0"
                if ident != "0" && ident.starts_with('0') {
                    return Err("leading zero in prerelease numeric".to_string());
                }
                // allowed
            } else {
                // must be alphanumeric or '-' and contain at least one letter or '-'
                if !ident.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
                    return Err("invalid prerelease identifier".to_string());
                }
                let has_letter_or_dash = ident.chars().any(|c| c.is_ascii_alphabetic() || c == '-');
                if !has_letter_or_dash {
                    return Err("invalid prerelease identifier".to_string());
                }
                // ok
            }
        }
        Some(pr.to_string())
    } else {
        None
    };

    // Validate build identifiers if present (already checked above)
    let build = if let Some(b) = build_part {
        Some(b.to_string())
    } else {
        None
    };

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(pr) = &v.prerelease {
        s.push('-');
        s.push_str(pr);
    }
    if let Some(b) = &v.build {
        s.push('+');
        s.push_str(b);
    }
    s
}

/// Helper: compare prerelease parts according to SemVer rules.
fn prerelease_parts(a: &str, b: &str) -> Ordering {
    let a_parts: Vec<&str> = a.split('.').collect();
    let b_parts: Vec<&str> = b.split('.').collect();
    let min_len = std::cmp::min(a_parts.len(), b_parts.len());
    for i in 0..min_len {
        let sa = a_parts[i];
        let sb = b_parts[i];
        let a_num = sa.chars().all(|c| c.is_ascii_digit());
        let b_num = sb.chars().all(|c| c.is_ascii_digit());
        match (a_num, b_num) {
            (true, true) => {
                let an = sa.parse::<u64>().unwrap();
                let bn = sb.parse::<u64>().unwrap();
                let c = an.cmp(&bn);
                if c != Ordering::Equal { return c; }
            }
            (true, false) => return Ordering::Less,
            (false, true) => return Ordering::Greater,
            (false, false) => {
                let c = sa.cmp(sb);
                if c != Ordering::Equal { return c; }
            }
        }
    }
    a_parts.len().cmp(&b_parts.len())
}

/// Semver precedence.
///
/// - build metadata is IGNORED entirely for precedence
/// - a version WITH a prerelease is LOWER than the same version without
/// - prerelease identifiers compare left to right, dot-separated
/// - all-numeric identifiers compare numerically
/// - all other identifiers compare lexically in ASCII order
/// - numeric identifiers always rank LOWER than non-numeric ones
/// - if all preceding identifiers are equal, more identifiers wins
pub fn compare(a: &Version, b: &Version) -> Ordering {
    // Numeric part first
    if a.major != b.major {
        return a.major.cmp(&b.major);
    }
    if a.minor != b.minor {
        return a.minor.cmp(&b.minor);
    }
    if a.patch != b.patch {
        return a.patch.cmp(&b.patch);
    }

    match (a.prerelease.as_ref(), b.prerelease.as_ref()) {
        (None, None) => Ordering::Equal,
        (None, Some(_)) => Ordering::Greater,
        (Some(_), None) => Ordering::Less,
        (Some(ra), Some(rb)) => prerelease_parts(ra, rb),
    }
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version { major: v.major.saturating_add(1), minor: 0, patch: 0, prerelease: None, build: None }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version { major: v.major, minor: v.minor.saturating_add(1), patch: 0, prerelease: None, build: None }
}

/// Increment patch; drop prerelease and build.
pub fn bump_patch(v: &Version) -> Version {
    Version { major: v.major, minor: v.minor, patch: v.patch.saturating_add(1), prerelease: None, build: None }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cmp::Ordering;

    // Helpers to avoid unwrap in tests
    fn ok<T>(r: Result<T, String>) -> T {
