    #[test]
    fn test_parse_valid_alpha_variants() {
        let v = ok(parse("1.0.0-alpha"));
        assert_eq!(v.major, 1);
        assert_eq!(v.minor, 0);
        assert_eq!(v.patch, 0);
        assert_eq!(v.prerelease.as_deref(), Some("alpha"));
