// Rust translation of reference/version.py (subset) with strict semantics

use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text after the '-' and '+' respectively,
/// or `None` if absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid SemVer 2.0.0 string.
///
/// Rules implemented exactly as in the Python reference:
/// - no leading zeros in major, minor, patch, or numeric prerelease identifiers
/// - prerelease and build identifiers may exist; build can have leading zeros
/// - must be in the form MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
/// - All three numeric components are required; no 'v' prefix.
pub fn parse(s: &str) -> Result<Version, String> {
    // Basic non-empty check
    if s.is_empty() {
        return Err("empty version".to_string());
    }

    // Split build metadata off '+'
    let (base, build_part) = match s.find('+') {
        Some(idx) => (&s[..idx], Some(&s[idx + 1..])),
        None => (s, None),
    };

    // Split prerelease off '-'
    let (core, prerelease_part) = match base.find('-') {
        Some(idx) => (&base[..idx], Some(&base[idx + 1..])),
        None => (base, None),
    };

    // core must be MAJOR.MINOR.PATCH exactly
    let parts: Vec<&str> = core.split('.').collect();
    if parts.len() != 3 {
        return Err(format!("{} is not valid SemVer string", s));
    }

    // Parse numeric components with no leading zeros
    let major = parse_num_no_leading_zero(parts[0])?;
    let minor = parse_num_no_leading_zero(parts[1])?;
    let patch = parse_num_no_leading_zero(parts[2])?;

    // Prerelease handling
    let prerelease = match prerelease_part {
        None => None,
        Some(p) => {
            if p.is_empty() {
                return Err("empty prerelease".to_string());
            }
            let idents: Vec<&str> = p.split('.').collect();
            if idents.iter().any(|id| id.is_empty()) {
                return Err("empty prerelease identifier".to_string());
            }
            // Validate identifiers and numeric leading zeros
            for id in &idents {
                if !is_valid_identifier(id) {
                    return Err("invalid prerelease identifier".to_string());
                }
                if id.chars().all(|c| c.is_ascii_digit()) {
                    // numeric identifier: must be 0 or non-leading-zero
                    if id.len() > 1 && id.starts_with('0') {
                        return Err("leading zero in numeric prerelease identifier".to_string());
                    }
                }
            }
            Some(p.to_string())
        }
    };

    // Build handling
    let build = match build_part {
        None => None,
        Some(b) => {
            if b.is_empty() {
                return Err("empty build".to_string());
            }
            let idents: Vec<&str> = b.split('.').collect();
            if idents.iter().any(|id| id.is_empty()) {
                return Err("empty build identifier".to_string());
            }
            for id in &idents {
                if !is_valid_identifier(id) {
                    return Err("invalid build identifier".to_string());
                }
            }
            Some(b.to_string())
        }
    };

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(ref pre) = v.prerelease {
        s.push('-');
        s.push_str(pre);
    }
    if let Some(ref b) = v.build {
        s.push('+');
        s.push_str(b);
    }
    s
}

/// Semver precedence.
///
/// Build metadata is ignored for precedence. A version without prerelease is greater
/// than the same version with a prerelease. Numeric prerelease parts compare numerically,
/// alphanumeric parts compare ASCII, numeric parts rank lower than alphanumeric, and
/// longer prerelease (more identifiers) ranks higher when all shared identifiers are equal.
pub fn compare(a: &Version, b: &Version) -> Ordering {
    // Compare major/minor/patch first
    if a.major != b.major {
        return a.major.cmp(&b.major);
    }
    if a.minor != b.minor {
        return a.minor.cmp(&b.minor);
    }
    if a.patch != b.patch {
        return a.patch.cmp(&b.patch);
    }

    // Prerelease comparison
    let r_a = a.prerelease.as_deref();
    let r_b = b.prerelease.as_deref();
    let rccmp = nat_cmp(r_a, r_b);
    if rccmp != 0 {
        // if either side has no prerelease, the one with no prerelease is greater
        if a.prerelease.is_none() {
            return Ordering::Greater;
        } else if b.prerelease.is_none() {
            return Ordering::Less;
        } else {
            return if rccmp < 0 { Ordering::Less } else { Ordering::Greater };
        }
    }

    // If prereleases are equal (including both None), they are equal in precedence
    Ordering::Equal
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

fn nat_cmp(a: Option<&str>, b: Option<&str>) -> i32 {
    // Normalize None to empty string as the Python version does
    let a_parts: Vec<&str> = a.unwrap_or("").split('.').collect();
    let b_parts: Vec<&str> = b.unwrap_or("").split('.').collect();

    let min_len = std::cmp::min(a_parts.len(), b_parts.len());
    for i in 0..min_len {
        let sa = a_parts[i];
        let sb = b_parts[i];
        let a_num = sa.chars().all(|c| c.is_ascii_digit());
        let b_num = sb.chars().all(|c| c.is_ascii_digit());

        let cmp = if a_num && b_num {
            // both numeric
            match (sa.parse::<u64>(), sb.parse::<u64>()) {
                (Ok(va), Ok(vb)) => va.cmp(&vb),
                // Fallback: compare as strings if parsing fails (shouldn't happen for valid digits)
                _ => sa.cmp(sb),
            }
        } else if a_num {
            // numeric < alphanumeric
            Ordering::Less
        } else if b_num {
            Ordering::Greater
        } else {
            sa.cmp(sb)
        };
        if cmp != Ordering::Equal {
            return match cmp {
                Ordering::Less => -1,
                Ordering::Equal => 0,
                Ordering::Greater => 1,
            };
        }
    }

    // If all common parts equal, longer prerelease wins
    if a_parts.len() == b_parts.len() {
        0
    } else if a_parts.len() > b_parts.len() {
        1
    } else {
        -1
    }
}

fn is_valid_identifier(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    s.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
}

fn parse_num_no_leading_zero(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("empty number".to_string());
    }
    if !s.chars().all(|c| c.is_ascii_digit()) {
        return Err("not a number".to_string());
    }
    if s.len() > 1 && s.starts_with('0') {
        return Err("leading zero".to_string());
    }
    match s.parse::<u64>() {
        Ok(n) => Ok(n),
        Err(e) => Err(format!("out of range: {}", e)),
    }
}

