use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// Reject, among others: leading zeroes (`01.0.0`), missing components
/// (`1.0`), negative numbers, empty identifiers (`1.0.0-`), and whitespace.
pub fn parse(s: &str) -> Result<Version, String> {
    // Disallow empty inputs
    if s.is_empty() {
        return Err("empty version".to_string());
    }

    // Split out build metadata (ignored for precedence)
    let (core, build_opt) = match s.split_once('+') {
        Some((c, b)) => {
            if b.is_empty() { return Err("empty build metadata".to_string()); }
            // Basic check: build metadata itself must be tokens separated by '.'
            // consisting of [0-9A-Za-z-]+. We do minimal validation here and rely on later parsing.
            (c, Some(b.to_string()))
        }
        None => (s, None),
    };

    // The prerelease part is separated by the first '-' from the core
    let (core_main, prerelease_opt) = match core.find('-') {
        Some(idx) => ( &core[..idx], Some(&core[idx+1..]) ),
        None => (core, None),
    };

    // Core must be exactly major.minor.patch (three numeric components)
    let nums: Vec<&str> = core_main.split('.').collect();
    if nums.len() != 3 {
        return Err("core version must be three numeric components".to_string());
    }

    // Validate numeric components (no leading zeros unless the number is exactly 0)
    fn parse_num(tok: &str) -> Result<u64, String> {
        if tok.is_empty() {
            return Err("empty numeric component".to_string());
        }
        if tok.len() > 1 && tok.as_bytes()[0] == b'0' {
            return Err("leading zero in numeric component".to_string());
        }
        // parse without using unwrap
        let mut val: u64 = 0;
        for ch in tok.bytes() {
            if ch < b'0' || ch > b'9' {
                return Err("non-numeric component".to_string());
            }
            val = val
                .saturating_mul(10)
                .saturating_add((ch - b'0') as u64);
        }
        Ok(val)
    }

    let major = parse_num(nums[0])?;
    let minor = parse_num(nums[1])?;
    let patch = parse_num(nums[2])?;

    // Validate prerelease if present
    let prerelease = if let Some(pr) = prerelease_opt {
        if pr.is_empty() {
            return Err("empty prerelease".to_string());
        }
        // prerelease identifiers are dot-separated
        let parts: Vec<&str> = pr.split('.').collect();
        if parts.is_empty() {
            return Err("empty prerelease".to_string());
        }
        // Each identifier must match PRERELEASE_IDENTIFIER pattern:
        // 0 | [1-9]\d* | \d*[A-Za-z-][0-9A-Za-z-]*
        for part in &parts {
            if part.is_empty() {
                return Err("empty prerelease identifier".to_string());
            }
            // helper to validate one identifier
            let valid_one = {
                // numeric only?
                let is_all_digits = part.chars().all(|c| c.is_ascii_digit());
                if is_all_digits {
                    // must be 0 or non-leading-zero
                    if part == "0" { true } else {
                        // must not start with '0'
                        part.as_bytes()[0] != b'0'
                    }
                } else {
                    // must contain at least one letter or '-' and only [0-9A-Za-z-]
                    let has_letter_or_dash = part.chars().any(|c| c.is_ascii_alphabetic() || c == '-');
                    if !has_letter_or_dash { false } else {
                        part.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
                    }
                }
            };
            if !valid_one {
                return Err("invalid prerelease identifier".to_string());
            }
        }
        Some(pr.to_string())
    } else {
        None
    };

    // Validate build metadata if present
    let build = if let Some(bm) = build_opt {
        if bm.is_empty() {
            return Err("empty build metadata".to_string());
        }
        // build identifiers are dot-separated, each must be [0-9A-Za-z-]+ (no empty bits)
        let bparts: Vec<&str> = bm.split('.').collect();
        if bparts.is_empty() {
            return Err("empty build metadata".to_string());
        }
        for part in &bparts {
            if part.is_empty() {
                return Err("empty build identifier".to_string());
            }
            if !part.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
                return Err("invalid build identifier".to_string());
            }
        }
        Some(bm)
    } else {
        None
    };

    Ok(Version { major, minor, patch, prerelease, build })
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(ref pre) = v.prerelease {
        s.push('-');
        s.push_str(pre);
    }
    if let Some(ref b) = v.build {
        s.push('+');
        s.push_str(b);
    }
    s
}

/// Semver precedence.
///
/// Careful — this is where naive translations break:
///   * build metadata is IGNORED entirely for precedence
///   * a version WITH a prerelease is LOWER than the same version without
///   * prerelease identifiers compare left to right, dot-separated
///   * all-numeric identifiers compare numerically
///   * all other identifiers compare lexically in ASCII order
///   * numeric identifiers always rank LOWER than non-numeric ones
///   * if all preceding identifiers are equal, more identifiers wins
///
/// The spec's own worked example, which you should be able to reproduce:
///   1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta
///     < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0
pub fn compare(a: &Version, b: &Version) -> Ordering {
    // Compare major, minor, patch first
    if a.major != b.major {
        return a.major.cmp(&b.major);
    }
    if a.minor != b.minor {
        return a.minor.cmp(&b.minor);
    }
    if a.patch != b.patch {
        return a.patch.cmp(&b.patch);
    }

    // Prerelease handling: None (no prerelease) > Some(prerelease)
    match (&a.prerelease, &b.prerelease) {
        (None, None) => Ordering::Equal,
        (None, Some(_)) => Ordering::Greater,
        (Some(_), None) => Ordering::Less,
        (Some(aa), Some(bb)) => {
            // dot-separated identifiers comparison
            fn parse_ident(s: &str) -> Vec<&str> { s.split('.').collect() }
            let a_parts = parse_ident(aa);
            let b_parts = parse_ident(bb);
            let mut i = 0;
            while i < a_parts.len() && i < b_parts.len() {
                let pa = a_parts[i];
                let pb = b_parts[i];
                let a_num = pa.chars().all(|c| c.is_ascii_digit());
                let b_num = pb.chars().all(|c| c.is_ascii_digit());
                if a_num && b_num {
                    // numeric compare with safe parsing (no unwrap)
                    let na = parse_u64_token(pa).unwrap();
                    let nb = parse_u64_token(pb).unwrap();
                    if na != nb {
                        return na.cmp(&nb);
                    }
                } else if a_num {
                    // numeric < non-numeric
                    return Ordering::Less;
                } else if b_num {
                    return Ordering::Greater;
                } else {
                    // both non-numeric: ASCII compare
                    if pa != pb {
                        return pa.cmp(pb);
                    }
                }
                i += 1;
            }
            // all shared identifiers equal; longer list wins
            a_parts.len().cmp(&b_parts.len())
        }
    }
}

fn parse_u64_token(tok: &str) -> Option<u64> {
    if tok.is_empty() { return None; }
    // no leading zeros for multi-digit numbers
    if tok.len() > 1 && tok.as_bytes()[0] == b'0' { return None; }
    let mut val: u64 = 0;
    for ch in tok.bytes() {
        if ch < b'0' || ch > b'9' { return None; }
        val = val.saturating_mul(10).saturating_add((ch - b'0') as u64);
    }
    Some(val)
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
///
/// Do not guess the prerelease interaction — read `reference/version.py`
/// and check against the oracle. `evaluate.py` compares you to the real
/// `semver` package on every bump of every valid version it generates.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

