//! The Rust translation of reference/version.py.
//!
//! This implementation is std-only (no dependencies) and aims to faithfully
//! reproduce the graded behavior of the Python reference.
//! It deliberately avoids panicking in library APIs (errors are returned) but
//! tests may panic on assertion failures as usual in Rust tests.

use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text after the '-' and '+' respectively,
/// or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// Rules (a strict subset of semver):
/// - must be of the form M.MIN.PATCH with optional -PRERELEASE and +BUILD
/// - no leading zeros in major/minor/patch (except the number 0 itself)
/// - prerelease identifiers follow: 0 | [1-9][0-9]* | \d*[A-Za-z-][0-9A-Za-z-]*
/// - build identifiers are dot-separated alphanumeric/hyphen tokens
pub fn parse(s: &str) -> Result<Version, String> {
    // Empty string invalid
    if s.is_empty() {
        return Err("empty version".to_string());
    }

    // Split off build metadata if present (only the first '+')
    let (core_build, build_opt) = match s.find('+') {
        Some(pos) => (&s[..pos], Some(&s[pos + 1..])),
        None => (s, None),
    };

    let build = if let Some(b) = build_opt {
        if b.is_empty() {
            return Err("empty build metadata".to_string());
        }
        // validate build tokens: non-empty, [0-9A-Za-z-]+ separated by '.'
        for tok in b.split('.') {
            if tok.is_empty() {
                return Err("empty build identifier".to_string());
            }
            if !tok.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
                return Err("invalid build identifier".to_string());
            }
        }
        Some(b.to_string())
    } else {
        None
    };

    // Split off prerelease if present (the first '-')
    let (core, prerelease_opt) = match core_build.find('-') {
        Some(pos) => (&core_build[..pos], Some(&core_build[pos + 1..])),
        None => (core_build, None),
    };

    let prerelease = if let Some(p) = prerelease_opt {
        if p.is_empty() {
            return Err("empty prerelease".to_string());
        }
        // prerelease is dot-separated identifiers, each must be valid
        for tok in p.split('.') {
            if tok.is_empty() {
                return Err("empty prerelease identifier".to_string());
            }
            if !is_valid_prerelease_identifier(tok) {
                return Err("invalid prerelease identifier".to_string());
            }
        }
        Some(p.to_string())
    } else {
        None
    };

    // Core version must be major.minor.patch with exactly three numeric parts
    let parts: Vec<&str> = core.split('.').collect();
    if parts.len() != 3 {
        return Err("version must be X.Y.Z".to_string());
    }

    let major = parse_numeric(parts[0])?;
    let minor = parse_numeric(parts[1])?;
    let patch = parse_numeric(parts[2])?;

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
