            }
            Ordering::Equal
        }
    }
}

fn nat_cmp(a: Option<&str>, b: Option<&str>) -> i32 {
    // Implement the comparison of prerelease identifiers as described.
    // Treat None as empty string for dot-split comparison, mirroring Python logic.
    let sa = a.unwrap_or("");
    let sb = b.unwrap_or("");
    let a_parts: Vec<&str> = sa.split('.').collect();
    let b_parts: Vec<&str> = sb.split('.').collect();
    for (pa, pb) in a_parts.iter().zip(b_parts.iter()) {
        let ca_num = pa.chars().all(|c| c.is_ascii_digit());
        let cb_num = pb.chars().all(|c| c.is_ascii_digit());
        let mut c = 0;
        if ca_num && cb_num {
            // parse as numbers
            let na = pa.parse::<i64>().unwrap_or(0);
            let nb = pb.parse::<i64>().unwrap_or(0);
            if na < nb {
                c = -1;
            } else if na > nb {
                c = 1;
            } else {
                c = 0;
            }
        } else if ca_num {
            c = -1; // numeric < non-numeric
        } else if cb_num {
            c = 1;
        } else {
            // both non-numeric: lexical ASCII compare
            match pa.cmp(pb) {
                std::cmp::Ordering::Less => c = -1,
                std::cmp::Ordering::Greater => c = 1,
                std::cmp::Ordering::Equal => c = 0,
