/// Increment patch; drop prerelease and build.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

fn parse_numeric(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("empty numeric".to_string());
    }
    if !s.chars().all(|c| c.is_ascii_digit()) {
        return Err("non-numeric".to_string());
    }
    // No leading zeros except the single '0'
    if s.len() > 1 && s.starts_with('0') {
        return Err("leading zeros not allowed".to_string());
    }
    match s.parse::<u64>() {
        Ok(n) => Ok(n),
        Err(_) => Err("number out of range".to_string()),
    }
}

fn is_valid_prerelease_identifier(tok: &str) -> bool {
    if tok.is_empty() {
