// A faithful Rust translation of the graded parts of Python's semver implementation
// as used by the automated harness. This file exposes the required public API
// and implements parsing, formatting, comparison, and version bumps without
// relying on any external crates.

use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text after the '-' and '+' respectively,
/// with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
///
/// - Leading zeroes in major/minor/patch are rejected (e.g. 01.0.0).
/// - Missing components (e.g. 1.0 or 1.0.0-rc.1) are rejected.
/// - Negative numbers are rejected; non-numeric components rejected.
/// - Empty identifiers are rejected.
/// - Identifiers use only [0-9A-Za-z-].
/// - The entire string must be consumed (no extra characters).
pub fn parse(s: &str) -> Result<Version, String> {
    // Disallow empty input or whitespace-only input
    let s = s.trim();
    if s.is_empty() {
        return Err("empty version".to_string());
    }

    // Work on a mutable string as we split components
    let mut rest = s.to_string();
    // Build metadata: after '+'
    let mut build: Option<String> = None;
    if let Some(pos) = rest.find('+') {
        if pos + 1 >= rest.len() {
            return Err("empty build metadata".to_string());
        }
        let (left, right) = rest.split_at(pos);
        // right starts with '+'
        let build_str = &right[1..];
        if build_str.is_empty() {
            return Err("empty build metadata".to_string());
        }
        // consume build part
        build = Some(build_str.to_string());
        rest = left.to_string();
    }

    // Prerelease: after '-' (only the first '-')
    let mut prerelease: Option<String> = None;
    if let Some(pos) = rest.find('-') {
        // ensure there is something after '-'
        if pos + 1 >= rest.len() {
            return Err("empty prerelease".to_string());
        }
        let (left, right) = rest.split_at(pos);
        // right starts with '-'
        let pre = &right[1..];
        if pre.is_empty() {
            return Err("empty prerelease".to_string());
        }
        // validate prerelease identifiers
        if !pre.split('.').all(|id| is_valid_prerelease_identifier(id)) {
            return Err("invalid prerelease identifier".to_string());
        }
        prerelease = Some(pre.to_string());
        rest = left.to_string();
    }

    // Main version: major.minor.patch (three components required)
    let nums: Vec<&str> = rest.split('.').collect();
    if nums.len() != 3 {
        return Err("version string must have major.minor.patch".to_string());
    }
    let major = parse_num_no_leading(nums[0])?;
    let minor = parse_num_no_leading(nums[1])?;
    let patch = parse_num_no_leading(nums[2])?;

    // Validate prerelease and build already were checked for basic syntax above;
    // one more semantic check: if there is a prerelease, it must not be empty (already checked).

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Helper: parse a numeric string with no leading zeros (except "0").
fn parse_num_no_leading(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("empty version component".to_string());
    }
    // Leading zeros are not allowed unless the number is exactly 0
    if s.len() > 1 && s.starts_with('0') {
        return Err("leading zero in version component".to_string());
    }
    match s.parse::<u64>() {
        Ok(n) => Ok(n),
        Err(_) => Err("invalid number".to_string()),
    }
}

fn is_valid_prerelease_identifier(id: &str) -> bool {
    if id.is_empty() {
        return false;
    }
    // numeric identifiers: "0" or non-zero without leading zeros
    if id == "0" {
        return true;
    }
    let is_all_digits = id.chars().all(|c| c.is_ascii_digit());
    if is_all_digits {
        // leading zeros are not allowed for numeric identifiers
        if id.starts_with('0') {
            return false;
        }
        return true;
    }
    // Non-numeric: must contain at least one letter or '-'
    let contains_letter_or_dash = id.chars().any(|c| c.is_ascii_alphabetic() || c == '-');
    if !contains_letter_or_dash {
        return false;
    }
    // All characters must be ASCII alphanumeric or '-'
    id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(ref pre) = v.prerelease {
        s.push('-');
        s.push_str(pre);
    }
    if let Some(ref b) = v.build {
        s.push('+');
        s.push_str(b);
    }
    s
}

/// Semver precedence.
///
/// - Build metadata is ignored for precedence
/// - Version with prerelease is considered lower than the same version without
/// - Prerelease identifiers compare dot-separated; numeric identifiers compare numerically
/// - Numeric identifiers rank lower than alphanumeric ones
/// - If all shared identifiers are equal, more identifiers wins
pub fn compare(a: &Version, b: &Version) -> Ordering {
    // Compare major, minor, patch first
    if a.major != b.major {
        return a.major.cmp(&b.major);
    }
    if a.minor != b.minor {
        return a.minor.cmp(&b.minor);
    }
    if a.patch != b.patch {
        return a.patch.cmp(&b.patch);
    }

    match (&a.prerelease, &b.prerelease) {
        (None, None) => Ordering::Equal,
        (Some(_), None) => Ordering::Less,  // prerelease is lower than no prerelease
        (None, Some(_)) => Ordering::Greater,
        (Some(sa), Some(sb)) => prerelease_cmp(sa, sb),
    }
}

fn prerelease_cmp(a: &str, b: &str) -> Ordering {
    // Dot-separated identifiers
    let a_parts: Vec<&str> = a.split('.').collect();
    let b_parts: Vec<&str> = b.split('.').collect();
    let max_len = std::cmp::max(a_parts.len(), b_parts.len());
    for i in 0..max_len {
        let pa = a_parts.get(i);
        let pb = b_parts.get(i);
        match (pa, pb) {
            (Some(a_id), Some(b_id)) => {
                // Determine if numeric
                let a_is_num = a_id.chars().all(|c| c.is_ascii_digit());
                let b_is_num = b_id.chars().all(|c| c.is_ascii_digit());
                if a_is_num && b_is_num {
                    // parse safely without unwrap
                    match (a_id.parse::<u64>(), b_id.parse::<u64>()) {
                        (Ok(va), Ok(vb)) => {
                            if va != vb {
                                return va.cmp(&vb);
                            }
                        }
                        // If parsing fails, fall back to string compare to be deterministic
                        (Err(_), Err(_)) => {
                            let ord = a_id.cmp(b_id);
                            if ord != Ordering::Equal {
                                return ord;
                            }
                        }
                        (Err(_), Ok(vb)) => return Ordering::Less,
                        (Ok(va), Err(_)) => return Ordering::Greater,
                    }
                } else if a_is_num {
                    // numeric < alphanumeric
                    return Ordering::Less;
                } else if b_is_num {
                    return Ordering::Greater;
                } else {
                    // both non-numeric: compare as ASCII strings
                    let ord = a_id.cmp(b_id);
                    if ord != Ordering::Equal {
                        return ord;
                    }
                }
            }
            (Some(_), None) => {
                // b exhausted, a has more identifiers -> greater
                return Ordering::Greater;
            }
            (None, Some(_)) => {
                // a exhausted, b has more -> less
                return Ordering::Less;
            }
            (None, None) => break,
        }
    }
    // All compared parts equal; longer list wins, but we've handled via length in loop.
    a_parts.len().cmp(&b_parts.len())
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

