///
/// Rules implemented to mirror Python's semver validation:
/// - three numeric components MAJOR.MINOR.PATCH with no leading zeros (except "0")
/// - optional prerelease after '-' consisting of dot-separated identifiers
/// - optional build after '+' consisting of dot-separated identifiers
/// - identifiers contain only [0-9A-Za-z-]
pub fn parse(s: &str) -> Result<Version, String> {
    // Empty string is invalid
    if s.is_empty() {
        return Err("empty version".to_string());
    }

    // Work on a working view; extract build part first
    let mut main = s;
    let mut build: Option<String> = None;
    if let Some(plus_idx) = main.find('+') {
        // build identifiers follow '+', must be non-empty and valid
        let b = &main[plus_idx + 1..];
        if b.is_empty() {
            return Err("empty build".to_string());
        }
        // validate build identifiers (ascii alnum or '-') separated by '.'
        for token in b.split('.') {
            if token.is_empty() {
                return Err("empty build token".to_string());
            }
            if !token.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
                return Err("invalid build token".to_string());
            }
        }
        build = Some(b.to_string());
        main = &main[..plus_idx];
        if main.is_empty() {
            // e.g. "+build" is invalid because there is no version before '+'
            return Err("invalid version before build".to_string());
        }
    }

    // Extract prerelease part
    let mut prerelease: Option<String> = None;
    if let Some(dash_idx) = main.find('-') {
        let pr = &main[dash_idx + 1..];
        if pr.is_empty() {
            return Err("empty prerelease".to_string());
        }
        // validate prerelease identifiers (dot-separated)
        for token in pr.split('.') {
            if token.is_empty() {
                return Err("empty prerelease token".to_string());
            }
            // token validation: either numeric (no leading zeros) or alphanumeric with dashes
            if token.chars().all(|c| c.is_ascii_digit()) {
                // numeric prerelease identifier
                if token.len() > 1 && token.starts_with('0') {
                    return Err("leading zero in prerelease numeric".to_string());
                }
            } else {
                // must be ascii alphanumeric or '-'
                if !token.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
                    return Err("invalid prerelease token".to_string());
                }
            }
        }
        prerelease = Some(pr.to_string());
        main = &main[..dash_idx];
        if main.is_empty() {
            return Err("invalid version before prerelease".to_string());
        }
    }

    // main must be MAJOR.MINOR.PATCH with exactly 3 components
    let mut parts = main.split('.');
    let major_s = parts.next().ok_or_else(|| "missing major".to_string())?;
    let minor_s = parts.next().ok_or_else(|| "missing minor".to_string())?;
    let patch_s = parts.next().ok_or_else(|| "missing patch".to_string())?;
    // ensure there are no extra parts
    if parts.next().is_some() {
        return Err("too many version parts".to_string());
    }

    let major = parse_numeric_component(major_s)?;
    let minor = parse_numeric_component(minor_s)?;
    let patch = parse_numeric_component(patch_s)?;

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

fn parse_numeric_component(part: &str) -> Result<u64, String> {
    if part.is_empty() {
        return Err("empty numeric component".to_string());
    }
    if part.len() > 1 && part.starts_with('0') {
        return Err("leading zero".to_string());
    }
    part
        .parse::<u64>()
        .map_err(|_| "not a number".to_string())
}

/// Render a `Version` back to its canonical string form.
/// `parse(&to_string(&v))` must round-trip for every valid `v`.
pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(ref pre) = v.prerelease {
        s.push('-');
        s.push_str(pre);
    }
    if let Some(ref b) = v.build {
        s.push('+');
        s.push_str(b);
    }
    s
}

/// Nat-like prerelease comparison according to semver rules.
fn compare_prerelease(a: &str, b: &str) -> Ordering {
    let a_parts: Vec<&str> = a.split('.').collect();
    let b_parts: Vec<&str> = b.split('.').collect();
    let max_len = a_parts.len().max(b_parts.len());

    for i in 0..max_len {
        let pa = a_parts.get(i);
        let pb = b_parts.get(i);
        match (pa, pb) {
            (Some(x), Some(y)) => {
                let a_num = x.chars().all(|c| c.is_ascii_digit());
                let b_num = y.chars().all(|c| c.is_ascii_digit());
                if a_num && b_num {
                    // parse numerically, with safe fallback
                    let ai = x.parse::<u64>().unwrap_or(0);
                    let bi = y.parse::<u64>().unwrap_or(0);
                    let ord = ai.cmp(&bi);
                    if ord != Ordering::Equal {
                        return ord;
                    }
                } else if a_num {
                    // numeric identifiers rank lower than alphanumeric
                    return Ordering::Less;
                } else if b_num {
                    return Ordering::Greater;
                } else {
                    // both alphanumeric: ASCII order
                    let ord = x.cmp(y);
                    if ord != Ordering::Equal {
                        return ord;
                    }
                }
            }
            (Some(_), None) => return Ordering::Greater,
            (None, Some(_)) => return Ordering::Less,
            (None, None) => break,
        }
    }
    a_parts.len().cmp(&b_parts.len())
}

/// Semver precedence: compare major/minor/patch then prerelease (if any), ignoring build.
pub fn compare(a: &Version, b: &Version) -> Ordering {
    // Compare major, minor, patch first
    if a.major != b.major {
        return a.major.cmp(&b.major);
    }
    if a.minor != b.minor {
        return a.minor.cmp(&b.minor);
    }
    if a.patch != b.patch {
        return a.patch.cmp(&b.patch);
    }

    match (&a.prerelease, &b.prerelease) {
        (None, None) => Ordering::Equal,
        (Some(_), None) => Ordering::Less,   // prerelease < release
        (None, Some(_)) => Ordering::Greater, // release > prerelease
        (Some(ap), Some(bp)) => compare_prerelease(ap.as_str(), bp.as_str()),
    }
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cmp::Ordering;

    // Helper: compare two semvers parsed from strings
    fn cmp(a: &str, b: &str) -> Result<Ordering, String> {
        let va = parse(a)?;
        let vb = parse(b)?;
        Ok(compare(&va, &vb))
    }

    #[test]
    fn test_parse_basic() -> Result<(), String> {
        let v = parse("1.0.0")?;
        assert_eq!(v.major, 1);
        assert_eq!(v.minor, 0);
        assert_eq!(v.patch, 0);
        assert!(v.prerelease.is_none());
        assert!(v.build.is_none());
        Ok(())
    }

    #[test]
    fn test_parse_prerelease_variants() -> Result<(), String> {
        let v = parse("1.0.0-alpha")?;
        assert_eq!(v.prerelease.as_deref(), Some("alpha"));
        assert!(v.build.is_none());

        let v2 = parse("1.0.0-alpha.1")?;
        assert_eq!(v2.prerelease.as_deref(), Some("alpha.1"));
        Ok(())
    }

    #[test]
    fn test_parse_build_variant() -> Result<(), String> {
        let v = parse("1.0.0+build")?;
        assert!(v.prerelease.is_none());
        assert_eq!(v.build.as_deref(), Some("build"));
        Ok(())
    }

    #[test]
    fn test_parse_invalid_leading_zero() -> Result<(), String> {
        // leading zero in major
        match parse("01.0.0") {
            Ok(_) => Err("expected error".to_string()),
            Err(_) => Ok(()),
        }
    }

    #[test]
    fn test_parse_invalid_missing_parts() -> Result<(), String> {
        // missing patch
        match parse("1.0") {
            Ok(_) => Err("expected error".to_string()),
            Err(_) => Ok(()),
        }
    }

    #[test]
    fn test_parse_invalid_empty_prerelease() -> Result<(), String> {
        // trailing '-' with nothing after
        match parse("1.0.0-") {
            Ok(_) => Err("expected error".to_string()),
            Err(_) => Ok(()),
        }
    }

    #[test]
    fn test_compare_chain() -> Result<(), String> {
        // 1.0.0-alpha < 1.0.0-alpha.1 < 1.0.0-alpha.beta < 1.0.0-beta < 1.0.0-beta.2 < 1.0.0-beta.11 < 1.0.0-rc.1 < 1.0.0
        assert_eq!(cmp("1.0.0-alpha", "1.0.0")?, Ordering::Less);
        assert_eq!(cmp("1.0.0-alpha.1", "1.0.0-alpha")?, Ordering::Greater);
        assert_eq!(cmp("1.0.0-alpha.beta", "1.0.0-alpha.1")?, Ordering::Greater);
        assert_eq!(cmp("1.0.0-beta", "1.0.0-alpha.beta")?, Ordering::Greater);
        assert_eq!(cmp("1.0.0-beta.2", "1.0.0-beta")?, Ordering::Greater);
        assert_eq!(cmp("1.0.0-beta.11", "1.0.0-beta.2")?, Ordering::Greater);
        assert_eq!(cmp("1.0.0-rc.1", "1.0.0-beta.11")?, Ordering::Greater);
        assert_eq!(cmp("1.0.0", "1.0.0")?, Ordering::Equal);
        Ok(())
    }

    #[test]
    fn test_bumps_and_roundtrip() -> Result<(), String> {
        // bump_patch drops prerelease/build and increments patch
        let v = parse("1.2.3")?;
        let vp = bump_patch(&v);
        assert_eq!(to_string(&vp), "1.2.4");

        // bump_major/minor saturating
        let vm = bump_major(&v);
        assert_eq!(to_string(&vm), "2.0.0");

        let vmi = parse("1.2.3-alpha.1+b1")?;
        let vmi_bp = bump_patch(&vmi);
        assert_eq!(to_string(&vmi_bp), "1.2.4");
        Ok(())
    }

    #[test]
    fn test_roundtrip_prerelease_build() -> Result<(), String> {
        let v = parse("1.0.0-alpha.1+bld.2")?;
        let s = to_string(&v);
        assert_eq!(s, "1.0.0-alpha.1+bld.2");
        // parse back round-trips
        let v2 = parse(&s)?;
        assert_eq!(v2, v);
        Ok(())
    }
}
